const rawInput = $input.first().json;
const body = (rawInput && typeof rawInput.body === 'object' && rawInput.body !== null) ? rawInput.body : rawInput;

function redact(val) {
  if (val === null || val === undefined) return null;
  return String(val)
    .replace(/Bearer\s+[A-Za-z0-9._~+/-]+=*/gi, 'Bearer [REDACTED]')
    .replace(/\b(nvapi|sk|ghp|gho|xoxb|xoxp|AIza)[A-Za-z0-9_-]{8,}\b/g, '[REDACTED_KEY]')
    .replace(/((?:x-usami-token|authorization|api[-_]?key|secret|password|token)\s*[:=]\s*)(["']?)[^\s,"';&}]+\2/gi, '$1[REDACTED]')
    .slice(0, 500);
}

const forbidden = new Set(['userMessage', 'reply', 'prompt', 'output', 'messages', 'parameters', 'result', 'authorization', 'cookie', 'x-usami-token']);
function cleanMeta(obj) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return {};
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    if (forbidden.has(k) || forbidden.has(k.toLowerCase())) continue;
    if (typeof v === 'string') out[k] = redact(v);
    else if (typeof v === 'number' || typeof v === 'boolean' || v === null) out[k] = v;
    else if (typeof v === 'object') out[k] = cleanMeta(v);
  }
  return out;
}

const statusCode = Number.isFinite(Number(body.statusCode)) ? Number(body.statusCode) : null;
const durationMs = Number.isFinite(Number(body.durationMs)) ? Math.round(Number(body.durationMs)) : null;
const kind = String(body.kind || 'api_call');
const source = String(body.source || 'usami-api');
const method = body.method ? String(body.method).toUpperCase() : null;
const route = body.route ? redact(String(body.route).split('?')[0]) : null;
const provider = body.provider ? redact(body.provider) : null;
const model = body.model ? redact(body.model) : null;
const clientId = body.clientId ? redact(body.clientId).slice(0, 64) : null;
const errorCode = body.errorCode ? redact(body.errorCode).slice(0, 64) : null;
const errorMessage = body.errorMessage ? redact(body.errorMessage) : null;
const isError = Boolean(body.isError || (statusCode !== null && statusCode >= 400) || kind === 'error' || errorMessage);
const shouldAlert = Boolean(kind === 'error' || (statusCode !== null && statusCode >= 500) || (isError && source !== 'usami-api') || (statusCode !== null && statusCode >= 400 && source !== 'usami-api'));
const timestamp = body.timestamp ? new Date(body.timestamp).toISOString() : new Date().toISOString();

const record = {
  timestamp,
  kind,
  source,
  method,
  route,
  statusCode,
  durationMs,
  provider,
  model,
  clientId,
  isError,
  errorCode,
  errorMessage: errorMessage || (statusCode >= 400 ? `HTTP ${statusCode} em ${method || 'REQ'} ${route || '/'}` : null),
  metadata: cleanMeta(body.metadata)
};

let envChannel = '';
try {
  envChannel = ($env && $env.DISCORD_OBS_ERRORS_CHANNEL_ID) ? String($env.DISCORD_OBS_ERRORS_CHANNEL_ID).trim() : '';
} catch {
  envChannel = '';
}
const obsErrorsChannelId = envChannel || String(body.channelsConfig?.obsErrorsChannelId || '').trim();
const hasErrorsChannel = Boolean(obsErrorsChannelId && !obsErrorsChannelId.startsWith('CONFIGURE_'));

const discordPayload = {
  embeds: [{
    title: `🚨 Erro de Observabilidade (${source})`,
    description: record.errorMessage || 'Erro registrado sem mensagem detalhada.',
    color: (statusCode && statusCode < 500) ? 16753920 : 15548997,
    fields: [
      { name: 'Origem', value: source, inline: true },
      { name: 'Rota / Fluxo', value: `${method ? method + ' ' : ''}${route || 'N/D'}`, inline: true },
      { name: 'Status', value: statusCode !== null ? String(statusCode) : 'N/D', inline: true },
      { name: 'Latência', value: durationMs !== null ? `${durationMs} ms` : 'N/D', inline: true },
      { name: 'Modelo / Provedor', value: [provider, model].filter(Boolean).join(' / ') || 'N/D', inline: true }
    ],
    timestamp
  }]
};

const payloadB64 = Buffer.from(JSON.stringify(record), 'utf8').toString('base64');

return [{
  json: {
    record,
    payloadB64,
    shouldAlert,
    obsErrorsChannelId,
    hasErrorsChannel,
    discordPayload
  }
}];
